                    if mask>>i & 1: nxt[i]-=1
                cost=price[s]+f(tuple(nxt))
                if cost<best: best=cost
        return best
    return f(state)

def high_groups(state):
    state=tuple(sorted(state, reverse=True))
    @lru_cache(None)
