from functools import lru_cache
from itertools import product
price=[0,800,1520,2160,2560,3000]
masks=[m for m in range(1,32) if 2 <= m.bit_count() <= 5]

@lru_cache(None)
def f_all(st):
    if not any(st): return 0
    best=sum(x*800 for x in st)
    for m in masks:
        if all(st[i] for i in range(5) if m>>i&1):
            nxt=list(st)
            for i in range(5):
                if m>>i&1: nxt[i]-=1
            best=min(best, price[m.bit_count()]+f_all(tuple(nxt)))
    return best

@lru_cache(None)
def f_high(st):
    st=tuple(sorted(st, reverse=True))
    if not any(st): return 0
    best=sum(x*800 for x in st)
    nonzero=sum(x>0 for x in st)
    for s in range(2,min(5,nonzero)+1):
        nxt=list(st)
        for i in range(s): nxt[i]-=1
        best=min(best, price[s]+f_high(tuple(nxt)))
    return best

for N in [2,3,4]:
    bad=[]
    for st in product(range(N+1), repeat=5):
        a,b=f_all(st),f_high(st)
        if a!=b:
            bad.append((st,a,b))
            if len(bad)>=5: break
    print('N',N,'bad',len(bad),bad[:5], 'allstates',f_all.cache_info().currsize, 'highstates',f_high.cache_info().currsize)
